import styled, { keyframes } from 'styled-components';

import { Text } from 'design';

const animate = keyframes`
    0% {
        background-position: 200% 50%;
    }

    100% {
        background-position: 0% 50%;
    }
`;

const Edges = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    to right,
    #35353a 68%,
    rgba(255, 255, 255, 0.8) 70%,
    #35353a 72%
  );
  animation: ${animate} 8s linear infinite forwards;
  background-size: 200% 100%;
  mask: url(data:image/svg+xml;base64,)
    no-repeat;
  z-index: 2;
  filter: ${p => (p.theme.type === 'light' ? 'none' : 'contrast(0.6)')};
`;

const Nodes = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 1;
  background: url(data:image/svg+xml;base64,)
    no-repeat;
  filter: ${p => (p.theme.type === 'light' ? 'invert(1)' : 'brightness(0.1)')};
`;

const Container = styled.div`
  display: flex;
  flex: 1;
  width: 100%;
  flex-direction: column;
  position: relative;
  justify-content: center;
  align-items: center;
`;

const Content = styled.div`
  width: 1200px;
  height: 280px;
  position: relative;
  opacity: 0.4;
`;

export function AccessGraphLoading() {
  return (
    <Container aria-busy="true">
      <Content>
        <Edges />
        <Nodes />
      </Content>

      <Text typography="h2">Launching Access Graph…</Text>
    </Container>
  );
}
